PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR
VAR
    Both_Req : BOOL;
END_VAR

Both_Req := OpenA_Cmd AND OpenB_Cmd;

IF OpenA_Cmd AND NOT Both_Req THEN
    DoorA := TRUE;
ELSE
    DoorA := FALSE;
END_IF;

IF (NOT OpenA_Cmd) AND OpenB_Cmd AND NOT Both_Req THEN
    DoorB := TRUE;
ELSE
    DoorB := FALSE;
END_IF;

END_PROGRAM

