PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR TON
    T1;
END_VAR

T1(IN := EStop OR (Level < LIQ_MIN AND (State = 1 OR State = 4)), PT := PT_REACT);

CASE State OF
    0: // Idle
        IF EStop OR NOT StartBatch THEN
            State := 0;
        ELSIF EStop OR Level < LIQ_MIN THEN
            State := 1;
        ELSIF Level >= LVL_HIGH AND Temp < TEMP_SET THEN
            State := 2;
        ELSIF Level >= LVL_HIGH AND Temp >= TEMP_SET AND T1.Q THEN
            State := 3;
        ELSIF Level <= LVL_LOW THEN
            State := 4;
        END_IF;

    1: // Fill
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        IF EStop OR Level >= LVL_HIGH OR NOT StartBatch THEN
            State := 0;
        ELSIF Level >= LVL_HIGH THEN
            State := 2;
        END_IF;

    2: // Heat
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        IF EStop OR Level < LIQ_MIN OR NOT StartBatch THEN
            State := 0;
        ELSIF Level >= LVL_HIGH AND Temp >= TEMP_SET AND T1.Q THEN
            State := 3;
        END_IF;

    3: // React
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        IF EStop OR Level < LIQ_MIN OR NOT StartBatch THEN
            State := 0;
        ELSIF T1.Q AND NOT T1.T#(PT_REACT) THEN
            State := 4;
        END_IF;

    4: // Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
        IF EStop OR Level <= LVL_LOW OR NOT StartBatch THEN
            State := 0;
        ELSIF Level <= LVL_LOW THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR
    State : INT;
END_VAR
VAR TON
    T1;
END_TON

T1(IN := TRUE, PT := PT_REACT);

CASE EStop OF
    | FALSE:
        State := 0;
    | TRUE:
        State := 0;
END_CASE;

CASE State OF
    | 0:  // Idle
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        IF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;
    | 1:  // Fill
        FillValve := Level < LVL_HIGH AND Level >= LIQ_MIN;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        IF NOT FillValve OR Level >= LVL_HIGH THEN
            State := 2;
        END_IF;
    | 2:  // Heat
        FillValve := FALSE;
        Heater := Temp < TEMP_SET AND Level >= LIQ_MIN;
        Agitator := TRUE;
        DrainValve := FALSE;
        IF Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
            State := 3;
        END_IF;
    | 3:  // React
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        IF T1.Q THEN
            State := 4;
        END_IF;
    | 4:  // Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := Level > LVL_LOW AND Level >= LIQ_MIN;
        IF Level <= LVL_LOW OR NOT DrainValve OR Level < LIQ_MIN THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

