        DrainValve := FALSE;
        IF NOT T1.Q THEN
            T1(IN := TRUE, PT := PT_REACT);
        END_IF;
        IF NOT T1.Q THEN
            State := 4;
        END_IF;
    | 4: // Drain
        FillValve := FALSE;
