IF EStop THEN
ELSIF StartBatch AND Level >= LIQ_MIN AND NOT EStop THEN
    CASE State OF
        | 0: IF Level < LVL_HIGH THEN State := 1 ELSE State := 2 END_IF;
        | 1: IF Level >= LVL_HIGH THEN State := 2 END_IF;
        | 2: IF Temp >= TEMP_SET THEN State := 3 END_IF;
        | 3: IF T_React.T#Elapsed THEN State := 4 END_IF;
        | 4: IF Level <= LVL_LOW THEN State := 0 END_IF;
    END_CASE;
END_IF;

CASE State OF
    | 0:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    | 1:
        FillValve := Level < LVL_HIGH;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    | 2:
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
    | 3:
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
    | 4:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := Level > LVL_LOW;
