VAR TON
    T1;
END_TON

T1(IN := TRUE, PT := PT_REACT);

CASE EStop OF
    | FALSE:
        State := 0;
    | TRUE:
END_CASE;

CASE State OF
    | 0: // Idle
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    | 1: // Fill
        IF Level >= LVL_HIGH OR Level < LIQ_MIN THEN
            State := 2;
        ELSIF EStop THEN
            State := 0;
        ELSE
            FillValve := TRUE;
        END_IF;
    | 2: // Heat
        IF Level < LIQ_MIN OR Temp >= TEMP_SET OR EStop THEN
            State := 2;
        ELSIF Level >= LVL_HIGH AND Temp < TEMP_SET AND NOT EStop THEN
            State := 3;
        ELSIF EStop THEN
            State := 0;
        ELSE
            Heater := TRUE;
            Agitator := TRUE;
        END_IF;
    | 3: // React
        IF Level < LIQ_MIN OR EStop OR T1.Q THEN
            State := 2;
        ELSIF EStop THEN
            State := 0;
        ELSIF Level >= LVL_HIGH AND T1.Q THEN
            State := 4;
        ELSIF EStop THEN
            State := 0;
        ELSE
            Heater := TRUE;
            Agitator := TRUE;
        END_IF;
    | 4: // Drain
        IF Level <= LVL_LOW OR EStop THEN
            State := 0;
        ELSIF EStop THEN
            State := 0;
        ELSE
            DrainValve := TRUE;
        END_IF;
END_CASE;

