    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR
    State : INT;
END_VAR
VAR_TON
    T1 : TON;
END_VAR

T1(IN := TRUE, PT := PT_REACT);

CASE EStop OF
    | FALSE:
        State := 0;
    | TRUE:
        State := 0;
END_CASE;

CASE State OF
    | 0: // Idle
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        IF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;
    | 1: // Fill
        FillValve := Level < LVL_HIGH AND Level >= LIQ_MIN;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        IF NOT FillValve OR Level >= LVL_HIGH OR NOT EStop THEN
            State := 2;
        END_IF;
    | 2: // Heat
        FillValve := FALSE;
        Heater := Temp < TEMP_SET;
        Agitator := Temp < TEMP_SET;
        DrainValve := FALSE;
        IF Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
            State := 3;
        END_IF;
    | 3: // React
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        IF T1.Q THEN
            State := 4;
        END_IF;
    | 4: // Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := Level > LVL_LOW AND Level >= LIQ_MIN;
        IF Level <= LVL_LOW OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR CONSTANT
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR
    State : INT;
END_VAR
VAR TON
    T_Fill : TON;
    T_React : TON;
END_VAR

T_Fill(IN := EStop OR (Level >= LVL_HIGH AND State = 1));
T_React(IN := EStop OR (State = 3));

CASE State OF
    0:  // Idle
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;

    1:  // Fill
        IF NOT EStop THEN
            FillValve := TRUE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
        ELSE
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
        END_IF;

    2:  // Heat
        IF NOT EStop AND Level >= LIQ_MIN THEN
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
        ELSE
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
        END_IF;

    3:  // React
        IF NOT EStop AND Level >= LIQ_MIN THEN
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
            T_React(IN := TRUE);
        ELSIF T_React.T# >= PT_REACT THEN
            State := 4;
        ELSE
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
        END_IF;

    4:  // Drain
        IF NOT EStop THEN
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := TRUE;
        ELSE
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
        END_IF;
END_CASE;

IF EStop OR Level < LVL_MIN THEN
    State := 0;
ELSIF StartBatch AND Level <= LVL_LOW THEN
    State := 1;
ELSIF Level >= LVL_HIGH AND Temp < TEMP_SET THEN
    State := 2;
ELSIF Level >= LVL_HIGH AND Temp >= TEMP_SET AND T_React.T# >= PT_REACT THEN
    State := 4;
ELSIF Level <= LVL_LOW AND Temp < TEMP_SET THEN
    State := 2;
END_IF;

END_PROGRAM

