PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR_TON
    T1;
END_VAR

T1(IN := EStop OR (Level < LIQ_MIN AND (State = 1 OR State = 4)), PT := PT_REACT);

CASE State OF
    0: // Idle
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        IF StartBatch AND EStop AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;

    1: // Fill
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        IF EStop OR Level >= LVL_HIGH THEN
            State := 2;
        END_IF;

    2: // Heat
        FillValve := FALSE;
        Heater := EStop OR (Level >= LIQ_MIN AND Temp < TEMP_SET);
        Agitator := EStop OR (Level >= LIQ_MIN AND Temp < TEMP_SET);
        DrainValve := FALSE;
        IF EStop OR (NOT EStop AND Level < LIQ_MIN) OR Temp >= TEMP_SET THEN
            State := 3;
        END_IF;

    3: // React
        FillValve := FALSE;
        Heater := EStop OR (Level >= LIQ_MIN AND Temp < TEMP_SET);
        Agitator := EStop OR (Level >= LIQ_MIN AND Temp < TEMP_SET);
        DrainValve := FALSE;
        IF EStop OR T1.Q THEN
            State := 4;
        END_IF;

    4: // Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := EStop OR Level <= LVL_LOW;
        IF EStop OR Level <= LVL_LOW THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR

IF NOT EStop THEN
    State := 0;
ELSIF StartBatch AND Level >= LIQ_MIN THEN
    CASE State OF
        0:
            IF Level >= LVL_HIGH THEN
                State := 1;
            END_IF;
        1:
            IF Level < LVL_HIGH THEN
                State := 1;
            ELSIF Temp >= TEMP_SET THEN
                State := 2;
            END_IF;
        2:
            IF Temp < TEMP_SET OR Level < LIQ_MIN THEN
                State := 2;
            ELSIF Level >= LVL_HIGH AND TimeElapsed(HeatTimer) >= PT_REACT#T#3s THEN
                State := 3;
            END_IF;
        3:
            IF Level < LIQ_MIN OR Temp < TEMP_SET THEN
                State := 3;
            ELSIF Level <= LVL_LOW THEN
                State := 4;
            END_IF;
        4:
            IF Level > LVL_LOW THEN
                State := 4;
            ELSE
                State := 0;
            END_IF;
    END_CASE;
END_IF;

CASE State OF
    0:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    1:
        FillValve := Level < LVL_HIGH;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    2:
        FillValve := FALSE;
        Heater := Temp < TEMP_SET;
        Agitator := TRUE;
        DrainValve := FALSE;
    3:
        FillValve := FALSE;
        Heater := Temp < TEMP_SET;
        Agitator := TRUE;
        DrainValve := FALSE;
    4:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := Level > LVL_LOW;
END_CASE;

END_PROGRAM

