    StopPB : BOOL;
    EStop : BOOL;
    Flame : BOOL;
END_VAR
VAR_OUTPUT
    Fan : BOOL;
    Fuel : BOOL;
    Ignition : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_PURGE : TIME := T#3s;
    PT_IGN : TIME := T#2s;
END_VAR

CASE State OF
    0: // Off
        IF (NOT EStop) OR StopPB OR StartPB THEN
            State := 0;
        ELSIF EStop AND (NOT EStop) THEN
            State := 1;
        END_IF;

    1: // Purge
        IF (NOT EStop) OR StopPB THEN
            State := 0;
        ELSIF EStop AND (NOT EStop) AND T#3s.PASSED THEN
            State := 2;
        END_IF;

    2: // Ignite
        IF (NOT EStop) OR StopPB OR (NOT Flame) THEN
            State := 0;
        ELSIF EStop AND (NOT EStop) AND T#2s.PASSED AND Flame THEN
            State := 3;
        END_IF;

    3: // Run
        IF (NOT EStop) OR StopPB OR (NOT Flame) THEN
            State := 0;
        END_IF;
END_CASE;

CASE State OF
    0:
        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;
    1:
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
    2:
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
    3:
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
END_CASE;

END_PROGRAM

PROGRAM burner
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
    Flame : BOOL;
END_VAR
VAR_OUTPUT
    Fan : BOOL;
    Fuel : BOOL;
    Ignition : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_PURGE : TIME := T#3s;
    PT_IGN : TIME := T#2s;
END_VAR

CASE State OF
    0:
        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF (StartPB AND EStop) OR StopPB THEN
            State := 0;
        ELSIF NOT EStop THEN
            State := 1;
        END_IF;

    1:
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF T#3s.PASSED(PT_PURGE) THEN
            State := 2;
        ELSIF (StartPB AND EStop) OR StopPB OR NOT EStop THEN
            State := 0;
        END_IF;

    2:
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        IF T#2s.PASSED(PT_IGN) THEN
            IF Flame THEN
                State := 3;
            ELSE
                State := 0;
            END_IF;
        ELSIF (StartPB AND EStop) OR StopPB OR NOT EStop THEN
            State := 0;
        END_IF;

    3:
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT Flame OR (StartPB AND EStop) OR StopPB OR NOT EStop THEN
            State := 0;
        END_IF;

END_CASE;

END_PROGRAM

PROGRAM burner
VAR_INPUT
    StartPB : BOOL;
    StopPB  : BOOL;
    EStop   : BOOL;
    Flame   : BOOL;
END_VAR
VAR_OUTPUT
    Fan     : BOOL;
    Fuel    : BOOL;
    Ignition: BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_PURGE : TIME := T#3s;
    PT_IGN : TIME := T#2s;
END_VAR

CASE State OF
    0: // Off
        IF (NOT EStop) OR StopPB OR StartPB THEN
            State := 0;
        ELSIF EStop THEN
            State := 0;
        END_IF;

    1: // Purge
        IF (NOT EStop) OR StopPB THEN
            State := 0;
        ELSIF Timer1.Q AND Timer2.Q THEN
            State := 2;
        ELSIF NOT Timer1.Q THEN
            Timer1(IN := TRUE, PT := PT_PURGE);
        ELSIF NOT Timer2.Q THEN
            Timer2(IN := TRUE, PT := PT_IGN);
        END_IF;

    2: // Ignite
        IF (NOT EStop) OR StopPB OR (NOT Flame) THEN
            State := 0;
        ELSIF EStop THEN
            State := 0;
        ELSIF NOT Timer1.Q THEN
            Timer1(IN := TRUE, PT := PT_IGN);
        ELSIF Timer1.Q AND Timer2.Q AND Flame THEN
            State := 3;
        END_IF;

    3: // Run
        IF (NOT EStop) OR StopPB OR (NOT Flame) THEN
            State := 0;
        ELSIF EStop THEN
            State := 0;
        END_IF;
END_CASE;

Fan := (State >= 1) AND EStop;
Fuel := (State >= 2) AND EStop;
Ignition := (State = 2) AND EStop AND Flame;

END_PROGRAM

