VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

CASE EStop OF
    FALSE:
        State := 0;
ELSIF StopPB OR (State > 0 AND NOT StartPB) THEN
    State := 0
ELSIF StartPB AND State = 0 THEN
    State := 1
ELSIF StartPB AND State = 1 AND T#2s.TimedOut THEN
    State := 2
ELSIF StartPB AND State = 2 AND T#2s.TimedOut THEN
    State := 3
END_IF;

